//! Row marks: Lucide 1.38.0 path data (ISC), the Omarchy cut ui/js/Icons.js carries, drawn as alpha masks.
//! Language logos are simple-icons geometry (CC0 1.0), trademarks of their owners, as ui/js/LangMarkPaths.js carries them.
use flea::protocol::RowFacts;
use gpui::SharedString;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Mark {
    Folder,
    /// A folder open in place in the List tree.
    FolderOpen,
    File,
    FileText,
    Code,
    Image,
    Film,
    Music,
    Archive,
    Type,
    Terminal,
    Table,
    Presentation,
    Symlink,
    /// A source file's language logo on the cut file page, ui/js/LangMarks.js.
    Language(Language),
}

macro_rules! svg {
    ($d:literal) => {
        concat!(
            r#"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" "#,
            r#"stroke-width="2" stroke-linecap="square" stroke-linejoin="miter"><path d=""#,
            $d,
            r#""/></svg>"#
        )
        .as_bytes()
    };
}

mod clip;
pub use clip::{ClipMark, ClipMarks};

impl Mark {
    /// Icons.js glyphForRow(): a symlink by its mode, everything else by its icon name.
    pub fn for_row(icon: &str, mode: u32) -> Self {
        if super::is_symlink(mode) {
            return Self::Symlink;
        }
        match icon {
            "folder" | "inode-directory" => Self::Folder,
            "text-x-generic" | "text-plain" | "x-office-document" => Self::FileText,
            "text-x-script" | "text-html" | "application-xml" => Self::Code,
            "image-x-generic" => Self::Image,
            "video-x-generic" => Self::Film,
            "audio-x-generic" => Self::Music,
            "package-x-generic" => Self::Archive,
            "font-x-generic" => Self::Type,
            "application-x-executable" => Self::Terminal,
            "x-office-spreadsheet" => Self::Table,
            "x-office-presentation" => Self::Presentation,
            _ => Self::File,
        }
    }

    /// Row.qml's slot: a code file wears its language's logo while language marks are on, every other row its kind's mark.
    pub fn for_facts(row: &RowFacts, languages: bool) -> Self {
        Self::for_file(&row.name, row.dir, row.mode, &row.icon, languages)
    }

    /// The same selector for subjects and peek rows that carry file facts without a protocol row.
    pub fn for_file(name: &str, dir: bool, mode: u32, icon: &str, languages: bool) -> Self {
        if languages && !dir && !super::is_symlink(mode) {
            if let Some(language) = Language::for_file(name) {
                return Self::Language(language);
            }
        }
        Self::for_row(icon, mode)
    }

    /// The Lucide name Icons.js binds, which Ipc.rowGlyph() reads through for_row(); a language logo is drawn on the file page.
    pub fn name(self) -> &'static str {
        match self {
            Self::Folder => "folder",
            Self::FolderOpen => "folder-open",
            Self::File | Self::Language(_) => "file",
            Self::FileText => "file-text",
            Self::Code => "code",
            Self::Image => "image",
            Self::Film => "film",
            Self::Music => "music",
            Self::Archive => "archive",
            Self::Type => "type",
            Self::Terminal => "terminal",
            Self::Table => "table",
            Self::Presentation => "presentation",
            Self::Symlink => "symlink",
        }
    }

    /// The atlas key and the SVG document; the key names the mark so each rasterizes once per size.
    pub fn svg(self) -> (SharedString, &'static [u8]) {
        let (key, data) = match self {
            Self::Language(language) => LOGOS[language.0 as usize],
            Self::Folder => ("flea-mark:folder", svg!("M2 20V3h6l2 3h12v14H2z")),
            Self::FolderOpen => (
                "flea-mark:folder-open",
                svg!("M2 20V3h6l2 3h12v3 M22 11l-2.5 9H2l2.5-9z"),
            ),
            Self::File => ("flea-mark:file", svg!("M4 22V2h10l6 6v14H4z M14 2v6h6")),
            Self::FileText => (
                "flea-mark:file-text",
                svg!("M4 22V2h10l6 6v14H4z M14 2v6h6 M8 9h2 M8 13h8 M8 17h8"),
            ),
            Self::Code => ("flea-mark:code", svg!("M16 18l6-6-6-6 M8 6l-6 6 6 6")),
            Self::Image => (
                "flea-mark:image",
                svg!("M3 3h18v18H3z M7 9A2 2 0 1 0 11 9A2 2 0 1 0 7 9Z M21 15l-3-3L6 21"),
            ),
            Self::Film => (
                "flea-mark:film",
                svg!("M3 3h18v18H3z M7 3v18 M3 7.5h4 M3 12h18 M3 16.5h4 M17 3v18 M17 7.5h4 M17 16.5h4"),
            ),
            Self::Music => (
                "flea-mark:music",
                svg!("M9 18V5l12-2v13 M3 15h6v6H3z M15 13h6v6h-6z"),
            ),
            Self::Archive => (
                "flea-mark:archive",
                svg!("M2 3h20v5H2z M4 8v13h16V8 M10 12h4"),
            ),
            Self::Type => ("flea-mark:type", svg!("M12 4v16 M4 7V4h16v3 M9 20h6")),
            Self::Terminal => ("flea-mark:terminal", svg!("M12 19h8 M4 17l6-6-6-6")),
            Self::Table => (
                "flea-mark:table",
                svg!("M3 3h18v18H3z M12 3v18 M3 9h18 M3 15h18"),
            ),
            Self::Presentation => (
                "flea-mark:presentation",
                svg!("M2 3h20 M3 3v13h18V3 M7 21l5-5 5 5"),
            ),
            Self::Symlink => ("flea-mark:symlink", svg!("M7 17L17 7 M8 7h9v9")),
        };
        (SharedString::new_static(key), data)
    }
}

/// One of the language logos LangMarks.js knows, by its slug's place in LOGOS.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Language(u8);

impl Language {
    /// LangMarks.slugForFile(): a known basename first, then the extension after the last dot; a leading dot is no extension.
    pub fn for_file(name: &str) -> Option<Self> {
        let lower = name.to_lowercase();
        let base = lower.rsplit('/').next().unwrap_or(&lower);
        let slug = FILES
            .iter()
            .find(|(file, _)| *file == base)
            .map(|(_, slug)| *slug)
            .or_else(|| {
                let dot = base.rfind('.').filter(|dot| *dot > 0)?;
                EXTS.iter()
                    .find(|(ext, _)| *ext == &base[dot..])
                    .map(|(_, slug)| *slug)
            })?;
        Self::for_slug(slug)
    }

    pub fn for_slug(slug: &str) -> Option<Self> {
        LOGOS
            .iter()
            .position(|(key, _)| key.strip_prefix(LOGO_KEY) == Some(slug))
            .map(|at| Self(at as u8))
    }

    pub fn slug(self) -> &'static str {
        let key: &'static str = LOGOS[self.0 as usize].0;
        &key[LOGO_KEY.len()..]
    }

    /// Every slug with a logo, in LangMarks.js KEYS order.
    pub fn slugs() -> impl Iterator<Item = &'static str> {
        (0..LOGOS.len()).map(|at| Self(at as u8).slug())
    }
}

