const LOGO_KEY: &str = "flea-lang:";

macro_rules! logo {
    ($slug:literal, $d:literal) => {
        (
            concat!("flea-lang:", $slug),
            concat!(
                r#"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" "#,
                r#"stroke-width="2" stroke-linecap="square" stroke-linejoin="miter"><path d="M4 7V2h10l6 6v14H17 M14 2v6h6"/>"#,
                r#"<path fill="currentColor" stroke="none" d=""#,
                $d,
                r#""/></svg>"#
            )
            .as_bytes(),
        )
    };
}

